const RUTE_BY_ID = new Map<string, string>();
const RUTE_BY_TITLE = new Map<string, string>();
const JUDUL_BY_PATH = new Map<string, string>();

for (const [id, rute, judul] of ENTRI_RUTE_KATALOG) {
  RUTE_BY_ID.set(id, rute);
  if (!RUTE_BY_TITLE.has(judul)) RUTE_BY_TITLE.set(judul, rute);
  if (!JUDUL_BY_PATH.has(rute)) JUDUL_BY_PATH.set(rute, judul);
}

export function dapatkanRuteKatalog(id: string, title: string): string | null {
  return RUTE_BY_ID.get(id) ?? RUTE_BY_TITLE.get(title) ?? null;
}

export function dapatkanJudulKatalog(pathname: string): string | null {
  return JUDUL_BY_PATH.get(pathname) ?? null;
}
